-- Focused migration-24 review regressions. Synthetic seed users; all changes roll back.
begin;
create temp table gn_checks(name text primary key);grant select,insert on gn_checks to authenticated,anon,service_role;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAILED %',label;end if;insert into pg_temp.gn_checks values(label);end$$;
create function pg_temp.denied(sql text,code text,label text) returns void language plpgsql as $$declare caught text;begin begin execute sql;exception when others then get stacked diagnostics caught=returned_sqlstate;end;perform pg_temp.ok(caught is not distinct from code,label||coalesce(' ['||caught||']',' [no error]'));end$$;
create function pg_temp.claim(n integer) returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('iss','https://gmvouqgjbtbkbhrdruzu.supabase.co/auth/v1','aud','authenticated','role','authenticated','sub','10000000-0000-0000-0000-'||lpad(n::text,12,'0'))::text,true)$$;
select pg_temp.ok((select relrowsecurity from pg_class where oid='private.group_notification_state'::regclass),'joining state RLS enabled');
select pg_temp.ok(not has_table_privilege('authenticated','private.group_notification_state','select'),'joining state private');
select pg_temp.ok(not has_function_privilege('authenticated','private.emit_group_joining_notice(uuid,uuid)','execute'),'students cannot emit joining notices');
select pg_temp.ok(not has_function_privilege('authenticated','private.emit_session_notice(text,text,uuid,uuid,uuid[])','execute'),'students cannot select session recipients');
select pg_temp.ok(not has_function_privilege('authenticated','private.notification_current(uuid,uuid)','execute'),'worker recipient inspection not exposed');
select pg_temp.ok(not has_function_privilege('authenticated','public.notification_worker(text,jsonb)','execute'),'worker remains server only');
select pg_temp.ok(has_function_privilege('service_role','public.notification_worker(text,jsonb)','execute'),'trusted worker remains callable');
select pg_temp.ok(bool_and(proconfig=array['search_path=""']),'session helpers use fixed empty search path') from pg_proc where pronamespace='private'::regnamespace and proname in ('emit_group_joining_notice','emit_session_notice','notification_current','notification_visible','group_notice_hash','session_notice_hash','group_notice_recipient','group_notice_upcoming','revoke_session_notices');

insert into public.enrollments(offering_id,user_id,status,enrolled_at) values('60000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000006','active',clock_timestamp());
select set_config('gn.schedules','[{"weekday":0,"time":"12:00","durationMinutes":60},{"weekday":3,"time":"12:00","durationMinutes":60}]',true);
select pg_temp.claim(2);set local role authenticated;
select set_config('gn.group',public.group_command(null,'create',null,jsonb_build_object('offeringId','60000000-0000-0000-0000-000000000001','name','Synthetic recurring notices','mode','online','joinUrl','https://meet.example.com/original','schedules',current_setting('gn.schedules')::jsonb))->>'id',true);
select pg_temp.ok((select count(*)>=24 from public.group_sessions where group_id=current_setting('gn.group')::uuid),'two weekly slots materialize approximately ninety days');
select set_config('gn.sessions',(select jsonb_agg(id order by id)::text from public.group_sessions where group_id=current_setting('gn.group')::uuid),true);
reset role;
select pg_temp.ok((select count(*)=0 from private.notification_events where resource_id=current_setting('gn.group')::uuid),'empty group materialization consumes no event keys');
set local role authenticated;
select public.group_command(current_setting('gn.group')::uuid,'add',1,'{"userId":"10000000-0000-0000-0000-000000000005"}');
select public.group_command(current_setting('gn.group')::uuid,'add',2,'{"userId":"10000000-0000-0000-0000-000000000006"}');
reset role;
select pg_temp.ok((select count(*)=1 from private.notification_events where resource_id=current_setting('gn.group')::uuid and event_type='session_details'),'one joining event for the timetable, not per occurrence');
select pg_temp.ok((select count(*)=2 from public.notifications n join private.notification_events e on e.id=n.event_id where e.resource_id=current_setting('gn.group')::uuid),'later members each receive one current announcement');
select pg_temp.ok((select count(distinct n.recipient_id)=2 from public.notifications n join private.notification_events e on e.id=n.event_id where e.resource_id=current_setting('gn.group')::uuid),'existing event extends to a later recipient');
select private.materialize_group(current_setting('gn.group')::uuid);select private.materialize_group(current_setting('gn.group')::uuid);
set local role authenticated;
select public.group_command(current_setting('gn.group')::uuid,'edit',3,jsonb_build_object('name','Synthetic recurring notices','schedules',current_setting('gn.schedules')::jsonb));
select pg_temp.ok((select jsonb_agg(id order by id)::text=current_setting('gn.sessions') from public.group_sessions where group_id=current_setting('gn.group')::uuid),'unchanged timetable preserves stable session IDs');
reset role;
select pg_temp.ok((select count(*)=2 from public.notifications n join private.notification_events e on e.id=n.event_id where e.resource_id=current_setting('gn.group')::uuid),'unchanged saves and materialization retries produce no duplicate alerts');
-- A long-idle materialization cursor can create historical records, never alerts.
update public.group_schedules set created_at=clock_timestamp()-interval '120 days',materialized_through=(clock_timestamp() at time zone 'Africa/Cairo')::date-120 where group_id=current_setting('gn.group')::uuid;
select private.materialize_group(current_setting('gn.group')::uuid);select private.materialize_group(current_setting('gn.group')::uuid);select private.materialize_group(current_setting('gn.group')::uuid);
select pg_temp.ok((select count(*)=2 from public.notifications n join private.notification_events e on e.id=n.event_id where e.resource_id=current_setting('gn.group')::uuid),'historical catch-up does not backfill old session notifications');

-- A configuration change is one revision; dated session snapshots are untouched.
select pg_temp.claim(5);set local role authenticated;
select public.notification_command('subscribe',jsonb_build_object('endpoint','https://fcm.googleapis.com/fcm/send/group-notice-test','p256dh',repeat('a',87),'auth',repeat('b',22)));
select public.notification_command('preference','{"event":"session_details","inApp":true,"push":true}');
select pg_temp.claim(2);
select public.group_command(current_setting('gn.group')::uuid,'edit',4,'{"joinUrl":"https://meet.example.com/revised"}');
select public.group_command(current_setting('gn.group')::uuid,'edit',5,'{"joinUrl":"https://meet.example.com/revised"}');
reset role;
select pg_temp.ok((select count(*)=2 from private.notification_events where resource_id=current_setting('gn.group')::uuid),'changed URL creates exactly one new joining revision');
select pg_temp.ok((select count(*)=1 from private.notification_events where resource_id=current_setting('gn.group')::uuid and revoked_at is not null),'old joining configuration notice revoked');
select pg_temp.ok((select bool_and(join_url='https://meet.example.com/original') from public.group_sessions where group_id=current_setting('gn.group')::uuid),'group notice does not overwrite dated URL snapshots');
select pg_temp.claim(5);set local role authenticated;
select pg_temp.ok((select count(*)=1 from public.notifications where event_type='session_details'),'direct table reads expose only current joining revision');
select pg_temp.ok((select count(*)=1 from jsonb_array_elements(public.notification_command('list')->'rows') x where x->>'event_type'='session_details'),'list RPC excludes superseded joining revision');
select pg_temp.claim(2);
select set_config('gn.recurring_session',(select id::text from public.group_sessions where group_id=current_setting('gn.group')::uuid and starts_at>clock_timestamp() order by starts_at limit 1),true);
select public.group_command(current_setting('gn.group')::uuid,'session',6,jsonb_build_object('sessionId',current_setting('gn.recurring_session'),'sessionVersion',0,'operation','reschedule','startsAt',clock_timestamp()+interval '2 hours','endsAt',clock_timestamp()+interval '3 hours'));
reset role;
select pg_temp.ok((select count(*)=1 from private.notification_events where session_id=current_setting('gn.recurring_session')::uuid and revoked_at is null),'intentional recurring exception reschedule creates one useful announcement');
select pg_temp.ok((select count(*)=1 from private.notification_deliveries d join public.notifications n on n.id=d.notification_id join private.notification_events e on e.id=n.event_id where e.session_id=current_setting('gn.recurring_session')::uuid and d.status='pending'),'reschedule queues opted-in recipient only');
set local role authenticated;
select public.group_command(current_setting('gn.group')::uuid,'session',7,jsonb_build_object('sessionId',current_setting('gn.recurring_session'),'sessionVersion',1,'operation','cancel','reason','Synthetic cancellation'));
reset role;
select pg_temp.ok((select bool_and(revoked_at is not null) from private.notification_events where session_id=current_setting('gn.recurring_session')::uuid),'cancelled occurrence notices revoked');
select pg_temp.ok((select bool_and(d.status='cancelled') from private.notification_deliveries d join public.notifications n on n.id=d.notification_id join private.notification_events e on e.id=n.event_id where e.session_id=current_setting('gn.recurring_session')::uuid),'cancellation revokes queued push leases');

-- Empty one-off group, late assignment, then late joining inside the reminder window.
select pg_temp.claim(2);set local role authenticated;
select set_config('gn.empty',public.group_command(null,'create',null,'{"offeringId":"60000000-0000-0000-0000-000000000002","name":"Synthetic empty online group","mode":"online","joinUrl":"https://meet.example.com/empty"}')->>'id',true);
select set_config('gn.oneoff',public.group_command(current_setting('gn.empty')::uuid,'one-off',1,jsonb_build_object('title','Synthetic one-off','startsAt',clock_timestamp()+interval '10 minutes','endsAt',clock_timestamp()+interval '70 minutes'))->>'sessionId',true);
reset role;
select pg_temp.ok((select count(*)=0 from private.notification_events where resource_id=current_setting('gn.empty')::uuid),'empty one-off group does not consume source keys');
set local role authenticated;
select public.group_command(current_setting('gn.empty')::uuid,'add',2,'{"userId":"10000000-0000-0000-0000-000000000006"}');
reset role;
select pg_temp.ok((select count(*)=1 from public.notifications n join private.notification_events e on e.id=n.event_id where e.resource_id=current_setting('gn.empty')::uuid),'first late member gets one upcoming summary, no session backfill');
set local role service_role;select public.notification_worker('sweep');select public.notification_worker('sweep');reset role;
select pg_temp.ok((select count(*)=1 from public.notifications n join private.notification_events e on e.id=n.event_id where e.session_id=current_setting('gn.oneoff')::uuid and e.event_type='session_starting'),'fifteen-minute reminder repeated sweep deduplicated');
select set_config('gn.fingerprint',private.session_notice_hash(current_setting('gn.oneoff')::uuid),true);
set local timezone='Asia/Tokyo';
select pg_temp.ok(private.session_notice_hash(current_setting('gn.oneoff')::uuid)=current_setting('gn.fingerprint'),'session identity is independent of connection timezone');
set local timezone='UTC';
insert into public.enrollments(offering_id,user_id,status,enrolled_at) values('60000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000005','active',clock_timestamp());
set local role authenticated;
select public.group_command(current_setting('gn.empty')::uuid,'add',3,'{"userId":"10000000-0000-0000-0000-000000000005"}');
reset role;set local role service_role;select public.notification_worker('sweep');select public.notification_worker('sweep');reset role;
select pg_temp.ok((select count(*)=2 from public.notifications n join private.notification_events e on e.id=n.event_id where e.session_id=current_setting('gn.oneoff')::uuid and e.event_type='session_starting'),'later recipient receives reminder without resending to existing recipient');
select pg_temp.ok((select count(*)=1 from private.notification_events where session_id=current_setting('gn.oneoff')::uuid and event_type='session_starting'),'late recipient shares one idempotent source event');
set local role authenticated;
select public.group_command(current_setting('gn.empty')::uuid,'session',4,jsonb_build_object('sessionId',current_setting('gn.oneoff'),'sessionVersion',0,'operation','cancel','reason','Synthetic cancellation'));
reset role;
select pg_temp.ok((select bool_and(revoked_at is not null) from private.notification_events where resource_id=current_setting('gn.empty')::uuid),'last upcoming cancellation invalidates summaries and reminders');
select pg_temp.claim(6);set local role authenticated;
select pg_temp.ok((select count(*)=0 from public.notifications where event_type='session_starting'),'cancelled reminder hidden by direct RLS read');
select pg_temp.ok((select count(*)=0 from jsonb_array_elements(public.notification_command('list')->'rows') x where x->>'event_type'='session_starting'),'cancelled reminder hidden by list RPC');
select pg_temp.claim(2);
select public.group_command(current_setting('gn.empty')::uuid,'session',5,jsonb_build_object('sessionId',current_setting('gn.oneoff'),'sessionVersion',1,'operation','restore','reason','Synthetic restore'));
reset role;set local role service_role;select public.notification_worker('sweep');select public.notification_worker('sweep');reset role;
select pg_temp.ok((select count(*)=1 from private.notification_events where session_id=current_setting('gn.oneoff')::uuid and event_type='session_starting' and revoked_at is null),'restore gets one new current reminder generation');
set local role authenticated;
select public.group_command(current_setting('gn.empty')::uuid,'session',6,jsonb_build_object('sessionId',current_setting('gn.oneoff'),'sessionVersion',2,'operation','reschedule','startsAt',clock_timestamp()+interval '2 days','endsAt',clock_timestamp()+interval '2 days 1 hour'));
reset role;set local role service_role;select public.notification_worker('sweep');reset role;
select pg_temp.ok((select count(*)=0 from private.notification_events where session_id=current_setting('gn.oneoff')::uuid and event_type='session_starting' and revoked_at is null),'reschedule outside reminder window leaves no upcoming-now claim');
select pg_temp.ok((select count(*)=1 from private.notification_events where session_id=current_setting('gn.oneoff')::uuid and event_type='session_details' and revoked_at is null),'reschedule retains only current useful details announcement');

-- Cross-tenant recipients, enrollment expiry, and unexposed URLs.
select pg_temp.claim(7);set local role authenticated;
select pg_temp.ok((select count(*)=0 from public.notifications where event_type in ('session_details','session_starting')),'other tenant receives no notices');
select pg_temp.denied($q$select public.group_view(current_setting('gn.group')::uuid,'sessions')$q$,'42501','other tenant cannot join using direct group RPC');
select pg_temp.denied($q$select public.group_command(current_setting('gn.group')::uuid,'add',8,'{"userId":"10000000-0000-0000-0000-000000000007"}')$q$,'42501','other tenant cannot self assign');
reset role;
select pg_temp.ok(not private.group_notice_recipient(current_setting('gn.group')::uuid,'10000000-0000-0000-0000-000000000007'),'recipient filter denies unrelated tenant');
update public.enrollments set enrolled_at=clock_timestamp()-interval '2 days',expires_at=clock_timestamp()-interval '1 second' where offering_id='60000000-0000-0000-0000-000000000002' and user_id='10000000-0000-0000-0000-000000000005';
select pg_temp.ok(not private.group_notice_recipient(current_setting('gn.empty')::uuid,'10000000-0000-0000-0000-000000000005'),'expired enrollment excluded from recipient set');
select pg_temp.claim(5);set local role authenticated;
select pg_temp.denied($q$select public.group_view(current_setting('gn.empty')::uuid,'sessions')$q$,'42501','expired enrollment cannot join session');
select pg_temp.ok(not exists(select 1 from public.notifications where to_jsonb(notifications)::text like '%https://meet.example.com%'),'notification payload contains no meeting URLs');
reset role;
-- Generic event helper is recipient-aware too, without replaying rows for prior recipients.
select private.emit_notification('empty-recipient-test','account_approved',null,gen_random_uuid(),'{}');
select pg_temp.ok(not exists(select 1 from private.notification_events where event_key='empty-recipient-test'),'empty generic event is not recorded');
select set_config('gn.resource',gen_random_uuid()::text,true);
select private.emit_notification('later-recipient-test','account_approved',null,current_setting('gn.resource')::uuid,array['10000000-0000-0000-0000-000000000005'::uuid]);
select private.emit_notification('later-recipient-test','account_approved',null,current_setting('gn.resource')::uuid,array['10000000-0000-0000-0000-000000000005'::uuid,'10000000-0000-0000-0000-000000000006'::uuid]);
select pg_temp.ok((select count(*)=2 from public.notifications n join private.notification_events e on e.id=n.event_id where e.event_key='later-recipient-test'),'generic source extends recipient set without duplicates');
select pg_temp.ok(not exists(select 1 from private.notification_events e where e.resource_id=current_setting('gn.group')::uuid and e.session_id is null and e.context_hash is null),'session contexts always recorded atomically');
-- Members assigned before the first timetable receive one summary when it appears.
select pg_temp.claim(3);set local role authenticated;
select set_config('gn.late_schedule',public.group_command(null,'create',null,'{"offeringId":"60000000-0000-0000-0000-000000000003","name":"Synthetic timetable published later","mode":"online","joinUrl":"https://meet.example.com/other-tenant"}')->>'id',true);
select public.group_command(current_setting('gn.late_schedule')::uuid,'add',1,'{"userId":"10000000-0000-0000-0000-000000000007"}');
reset role;
select pg_temp.ok((select count(*)=0 from private.notification_events where resource_id=current_setting('gn.late_schedule')::uuid),'assignment without an upcoming class consumes no key');
set local role authenticated;
select public.group_command(current_setting('gn.late_schedule')::uuid,'edit',2,jsonb_build_object('schedules',current_setting('gn.schedules')::jsonb));
reset role;
select pg_temp.ok((select count(*)=1 from public.notifications n join private.notification_events e on e.id=n.event_id where e.resource_id=current_setting('gn.late_schedule')::uuid),'first timetable after assignment announces once');
select pg_temp.ok((select count(*)=1 from private.notification_events where resource_id=current_setting('gn.late_schedule')::uuid),'first ninety-day materialization shares one joining source');
select pg_temp.claim(5);set local role authenticated;
select pg_temp.denied($q$select public.group_view(current_setting('gn.late_schedule')::uuid,'sessions')$q$,'42501','new other-tenant joining URL remains inaccessible');
reset role;
select count(*) group_notification_tests from pg_temp.gn_checks;
rollback;
